import CoreGraphics
import SwiftUI

/// Parses the icon path data generated by `scripts/port/extract-icons.mjs`.
///
/// The extractor already flattened every SVG primitive — `rect`, `circle`, `ellipse`,
/// `line`, `polyline`, `polygon`, quadratic curves and elliptical arcs — into absolute
/// cubic curves. This parser therefore only has to understand `M`, `L`, `C` and `Z`.
///
/// Path data is written in the icon's own 512x512 authoring box, so the result is scaled
/// by `size / 512`. Malformed input never traps: unreadable commands are skipped and the
/// path keeps whatever it parsed so far.
public enum SVGPath {
  /// Parses absolute M/L/C/Z path data and scales the 512x512 authoring box to `size`.
  public static func cgPath(_ d: String, size: CGSize) -> CGPath {
    let path = CGMutablePath()
    guard size.width > 0, size.height > 0 else {
      return path
    }
    let scaleX = size.width / 512
    let scaleY = size.height / 512
    let characters = Array(d)
    var index = 0
    var command: Character?
    var subpathStart = CGPoint.zero
    var hasSubpath = false

    func skipSeparators() {
      while index < characters.count {
        let character = characters[index]
        if character == " " || character == "," || character == "\n" || character == "\t"
          || character == "\r"
        {
          index += 1
        } else {
          break
        }
      }
    }

    func readNumber() -> Double? {
      skipSeparators()
      let start = index
      while index < characters.count {
        let character = characters[index]
        if character.isNumber || character == "." || character == "-" || character == "+"
          || character == "e" || character == "E"
        {
          index += 1
        } else {
          break
        }
      }
      guard index > start else {
        return nil
      }
      return Double(String(characters[start..<index]))
    }

    func point(_ x: Double, _ y: Double) -> CGPoint {
      CGPoint(x: x * scaleX, y: y * scaleY)
    }

    while index < characters.count {
      let character = characters[index]
      if character.isLetter {
        index += 1
        switch Character(character.uppercased()) {
        case "M": command = "M"
        case "L": command = "L"
        case "C": command = "C"
        case "Z": command = "Z"
        default: command = nil
        }
        if command == "Z" {
          if hasSubpath {
            path.closeSubpath()
          }
          hasSubpath = false
          command = nil
          continue
        }
      }

      guard let active = command else {
        index += 1
        continue
      }

      switch active {
      case "M":
        guard let x = readNumber(), let y = readNumber() else {
          command = nil
          continue
        }
        let start = point(x, y)
        path.move(to: start)
        subpathStart = start
        hasSubpath = true
        command = "L"
      case "L":
        guard let x = readNumber(), let y = readNumber() else {
          command = nil
          continue
        }
        if !hasSubpath {
          path.move(to: subpathStart)
          hasSubpath = true
        }
        path.addLine(to: point(x, y))
      case "C":
        guard let x1 = readNumber(), let y1 = readNumber(), let x2 = readNumber(),
          let y2 = readNumber(), let x = readNumber(), let y = readNumber()
        else {
          command = nil
          continue
        }
        if !hasSubpath {
          path.move(to: subpathStart)
          hasSubpath = true
        }
        path.addCurve(to: point(x, y), control1: point(x1, y1), control2: point(x2, y2))
      default:
        command = nil
      }
    }

    return path
  }
}

/// Draws one of the ported Excalidraw icons.
///
/// Shapes are drawn in the order the extractor wrote them. Filled shapes use `color` as
/// their fill; stroked shapes use `color` with round caps and joins and the stroke width
/// the source icon used, scaled from the 512x512 box to `size`.
public struct PortIconView: View {
  private let shapes: [IconShape]
  private let size: CGFloat
  private let color: Color

  /// Renders `name`, or nothing visible if the name is unknown.
  public init(name: String, size: CGFloat, color: Color) {
    self.shapes = PortIcons.icon(name)?.shapes ?? []
    self.size = size
    self.color = color
  }

  public var body: some View {
    ZStack {
      ForEach(Array(shapes.enumerated()), id: \.offset) { item in
        shapeView(item.element)
      }
    }
    .frame(width: size, height: size)
    .accessibilityHidden(true)
  }

  private func shapeView(_ shape: IconShape) -> some View {
    let path = Path(SVGPath.cgPath(shape.d, size: CGSize(width: size, height: size)))
    return Group {
      if shape.filled {
        path.fill(color)
      } else {
        path.stroke(
          color,
          style: StrokeStyle(
            lineWidth: shape.strokeWidth * size / 512,
            lineCap: .round,
            lineJoin: .round))
      }
    }
  }
}
